<file path="src/reports.js">
import { daysBetween } from './dates.js';
import { balanceDue } from './payments.js';
import { lineTotal } from './invoices.js';
import { roundCents } from './money.js';

/**
 * Find overdue invoices.
 * @param {Array<{ number: string, customerId: string, status: string, dueDate: string, payments?: Array, lines: Array }>} invoices
 * @param {string} asOf - YYYY-MM-DD format
 * @returns {Array<{ number: string, customerId: string, dueDate: string, daysOverdue: number, due: number }>}
 */
export function overdueInvoices(invoices, asOf) {
  return invoices
    .filter(inv => inv.status === 'issued' || inv.status === 'partially_paid')
    .filter(inv => inv.dueDate < asOf)
    .map(inv => ({
      number: inv.number,
      customerId: inv.customerId,
      dueDate: inv.dueDate,
      daysOverdue: daysBetween(inv.dueDate, asOf),
      due: balanceDue(inv),
    }))
    .sort((a, b) => b.daysOverdue - a.daysOverdue);
}

/**
 * Calculate VAT summary by rate.
 * @param {Array<{ status: string, lines: Array<{ qty: number, unitPrice: number, discountPercent?: number, vatRate?: number }> }>} invoices
 * @returns {Array<{ rate: number, base: number, vat: number }>}
 */
export function vatSummary(invoices) {
  const vatMap = new Map();

  for (const invoice of invoices) {
    if (!['issued', 'partially_paid', 'paid'].includes(invoice.status)) continue;

    for (const line of invoice.lines) {
      const lineAmount = lineTotal(line);
      const discount = lineAmount * (line.discountPercent ?? 0) / 100;
      const base = Math.max(0, lineAmount - discount);
      const vatAmount = roundCents(base * (line.vatRate ?? 0) / 100);
      const rate = line.vatRate ?? 0;

      if (!vatMap.has(rate)) {
        vatMap.set(rate, { base: 0, vat: 0 });
      }
      const entry = vatMap.get(rate);
      entry.base += base;
      entry.vat += Math.max(0, vatAmount);
    }
  }

  return Array.from(vatMap)
    .map(([rate, { base, vat }]) => ({ rate, base, vat }))
    .sort((a, b) => b.rate - a.rate);
}

/**
 * Calculate late fee for an invoice: 0.04% of amount due per day overdue.
 * @param {{ dueDate: string, status: string, payments?: Array, lines: Array }} invoice
 * @param {string} asOf - YYYY-MM-DD format
 * @returns {number}
 */
export function lateFee(invoice, asOf) {
  if (invoice.dueDate >= asOf) {
    return 0;
  }

  const amountDue = balanceDue(invoice);
  if (amountDue <= 0) {
    return 0;
  }

  const daysOverdue = daysBetween(invoice.dueDate, asOf);
  const fee = roundCents(amountDue * 0.0004 * daysOverdue);
  return Math.max(0, fee);
}
